from pathlib import Path
from playwright.sync_api import sync_playwright
import base64
root=Path(__file__).resolve().parent.parent
font=base64.b64encode((root/'public/fonts/Cairo.ttf').read_bytes()).decode()
style='<style>@font-face{font-family:Cairo;src:url(data:font/ttf;base64,'+font+')}*{box-sizing:border-box}body{margin:0;font-family:Cairo;color:#173D56;background:white} .label{color:#7996A6;font-size:21px} .card{border:1px solid #DDE9EE;border-radius:20px;background:white;padding:26px}.muted{color:#7F99A7}.bubble{padding:25px;border-radius:22px;background:#EAF5EF;font-size:30px;line-height:1.9}</style>'
browser='''<div style="height:50px;background:#EAF1F5;padding:10px 26px;display:flex;align-items:center;gap:10px" dir=ltr><span style="color:#7895A5">● ● ●</span><div style="background:white;text-align:center;width:700px;border-radius:8px;margin:auto;color:#86A1AF">beon.chat</div></div><div dir=rtl style="display:flex;height:750px"><div style="width:76px;background:#0F578D;color:white;font-size:33px;padding:30px 20px;line-height:2.5">▣<br>☷<br>♧<br>◷</div><div style="width:265px;padding:25px;border-left:1px solid #E5EDF1"><h2 style="font-size:28px">المحادثات</h2><p class=muted>بحث في المحادثات</p><div style="background:#E9F3F8;padding:22px;border-radius:15px;border-right:4px solid #10994D"><b style="font-size:24px">عميل تجريبي</b><p>ممكن تفاصيل؟</p></div><div style="height:10px;width:130px;background:#E6EEF3;margin:45px 20px 18px;border-radius:5px"></div><div style="height:8px;width:170px;background:#F1F5F7;margin:0 20px;border-radius:5px"></div></div><div style="padding:30px;flex:1;background:#F5F9FB"><div style="font-size:29px;font-weight:700;border-bottom:1px solid #DEEBF1;padding:5px 0 25px">عميل تجريبي</div><div class=card style="margin-top:38px;font-size:32px">ممكن تفاصيل؟<p class=label>١٠:٣٠ ص</p></div><div class=bubble style="margin:30px 35px 0 0">أهلًا بيك، نقدر نساعدك.</div><div style="margin-top:160px;padding:16px;background:white;border:1px solid #E1EBF1;border-radius:13px;color:#8CA3B0">المحادثة</div></div><div style="width:280px;padding:30px;border-right:1px solid #E5EDF1"><h2>ملف العميل</h2><div class=card style="padding:20px;margin-top:34px"><div class=label>بيانات العميل</div><h3 style="font-size:24px">عميل تجريبي</h3><p>استفسار عن الخدمة</p></div><div style="padding:20px;margin-top:30px"><div class=label>المسؤول</div><h3 style="font-size:24px">عضو الفريق ١</h3></div></div></div>'''
mobile='''<div dir=rtl style="padding:38px;height:1600px;position:relative"><div dir=ltr style="font-size:25px;display:flex;justify-content:space-between"><span>9:41</span><span>▮▮▮ ▰</span></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:40px"><div style="display:flex;align-items:center;gap:18px"><span style="display:grid;place-items:center;background:#E4F2F8;border-radius:50%;width:83px;height:83px;font-size:34px;color:#0F578D">ف</span><div><div class=label>مساء الخير</div><b style="font-size:31px">فريق تجريبي</b></div></div><span style="font-size:44px;color:#0F578D">⌕</span></div><div style="margin-top:55px;background:linear-gradient(100deg,#0F578D,#3BA2CF);color:white;border-radius:33px;padding:35px"><div style="font-size:28px">تواصل أوضح. متابعة أسهل.</div><div style="font-size:42px;font-weight:700;margin-top:16px">شغلك معاك</div></div><h2 style="font-size:30px;margin-top:50px">إجراءات سريعة</h2><div style="display:flex;gap:14px">'''+''.join('<div class=card style="flex:1;text-align:center;padding:24px 7px"><div style="font-size:38px;color:#0F578D">'+icon+'</div><div style="font-size:20px;margin-top:18px">'+title+'</div></div>' for icon,title in [('☷','المحادثات'),('♧','جهات الاتصال'),('▥','التقارير')])+'''</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:45px"><h2 style="font-size:29px">أحدث المحادثات</h2><span style="color:#10994D;font-size:23px">عرض الكل</span></div><div class=card><div style="display:flex;gap:20px;align-items:center"><span style="width:66px;height:66px;background:#E2F0F6;border-radius:50%;display:grid;place-items:center;font-size:25px">ع</span><div><b style="font-size:28px">عميل تجريبي</b><p style="font-size:25px;color:#6A8A9C;margin:8px 0">ممكن تفاصيل؟</p></div></div></div><div style="position:absolute;bottom:0;right:0;left:0;height:160px;background:#F6F9FB;display:flex;justify-content:space-around;align-items:center;font-size:23px;color:#7693A3"><span style="color:#0F578D">الرئيسية</span><span>جهات الاتصال</span><span>التقارير</span></div></div>'''
message='<div dir=rtl style="padding:30px 42px;background:white;border-radius:28px;height:300px;border-right:12px solid #10994D"><div style="font-size:26px;color:#10994D">استفسار جديد</div><div style="font-size:59px;font-weight:700;margin-top:5px">ممكن تفاصيل؟</div><div style="font-size:22px;color:#829BAA;margin-top:8px">عميل تجريبي</div></div>'
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 for name,w,h,body in [('browser-preview',1280,800,browser),('mobile-preview',704,1600,mobile),('message',900,300,message),('message-secondary',900,300,message.replace('ممكن تفاصيل؟','محتاج مساعدة').replace('استفسار جديد','رسالة جديدة').replace('#10994D','#0F578D'))]:
  page=b.new_page(viewport={'width':w,'height':h},device_scale_factor=1);page.set_content(style+body);page.evaluate('document.fonts.ready');page.screenshot(path=str(root/'public/screens'/f'{name}.png'));page.close()
 b.close()
